fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    assert_eq!(a.len(), b.len(), "input arrays must have equal length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x < y)
        .collect()
}